<script setup>
defineProps({ entry: Object, panel: Object, qualityName: String, qualityColor: String, traits: Array, manual: Boolean });
const channels = { physical: '物理', magic: '魔力', fire: '火', lightning: '雷', holy: '圣' };
function amount(value) { return typeof value === 'number' && Number.isFinite(value) ? value.toLocaleString('zh-CN', { maximumFractionDigits: 2 }) : '—'; }
</script>

<template>
  <article class="equipment-card" :class="`quality-${qualityColor}`" aria-label="当前武器装备卡">
