    <div class="equipment-body">
      <div class="equipment-portrait"><img :src="entry.weaponImage" :alt="entry.name"></div>
      <div class="equipment-attributes"><p>{{ manual ? '手填最终面板' : '面板攻击 · 参数推算' }}</p><dl><div v-for="(name, key) in channels" :key="key" :class="{ zero: panel?.[key] === 0 }"><dt><img :src="`/enemy-attribute-icons/damage-${key}.png`" alt="">{{ name }}</dt><dd>{{ amount(panel?.[key]) }}</dd></div></dl></div>
    </div>
    <div v-if="entry.statuses?.length" class="equipment-statuses"><span v-for="status in entry.statuses" :key="status.name"><img :src="status.icon" alt="">{{ status.name }}</span><small>固有异常积累</small></div>
    <div class="equipment-art"><img :src="entry.artImage" alt=""><div><small>战技</small><strong>{{ entry.artName }}</strong></div></div>
    <ul class="equipment-traits"><li v-for="slot in traits" :key="slot.id" :class="{ negative: slot.polarity === 'negative', empty: !slot.name }"><span>{{ slot.polarity === 'negative' ? '−' : slot.polarity === 'corpse' ? '◇' : '+' }}</span><div>{{ slot.name || '未选择词条' }}<small v-if="slot.detail" class="equipment-trait-detail">{{ slot.detail }}</small></div></li></ul>
  </article>
</template>

